mapper.select:
select * from (SELECT T1.ENTRUST_ID entrustId ,T1.ENTRUST_STATUS entrustStatus, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T4.ORDER_FINISH_AMT, 0 ),0,0, nvl( T4.ORDER_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_NUM, 1 )), 4 ) ELSE ROUND( decode(nvl( T4.ORDER_FINISH_AMT, 0 ),0,0, nvl( T4.ORDER_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_AMT, 1 )), 4 ) END AS implementPercent, CASE
WHEN T2.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T4.ENT_FINISH_AMT, 0 ),0 ,0 , nvl( T4.ENT_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_NUM, 1 )), 4 ) ELSE ROUND( decode(nvl( T4.ENT_FINISH_AMT, 0 ),0,0, nvl( T4.ENT_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_AMT, 1 )), 4 ) END AS dealPercent, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T4.ORDER_FINISH_AMT/100, 0 ), 4 ) ELSE ROUND( nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) END AS finishAmt, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( (nvl( T1.ENTRUST_NUM, 0 ) - nvl( T4.ORDER_FINISH_AMT, 0 ))/100, 4 ) ELSE ROUND( nvl( T1.ENTRUST_AMT, 0 ) - nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) END AS avaNum, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T4.ENT_FINISH_AMT/100, 0 ), 4 ) ELSE ROUND( nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) END AS finishDealAmt, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( (nvl( T1.ENTRUST_NUM, 0 ) - nvl( T4.ENT_FINISH_AMT, 0 ))/100, 4 ) ELSE ROUND( nvl( T1.ENTRUST_AMT, 0 ) - nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) END AS avaDealAmt, nvl(detail.PORTFOLIO_ID,T5.PORTFOLIO_ID) portfolioId, nvl(detail.PORTFOLIO_NAME,T5.PORTFOLIO_NAME) portfolioName, T1.FINPROD_ID finprodId ,T7.FINPROD_MARKET_ID AS FINPROD_MARKET_ID ,T7.FINPROD_ABBR AS finprodAbbr ,T1.FINPROD_TYPE2 finprodType2 ,T1.TRADE_MARKET tradeMarket ,T1.TRADE_PLAT ,T1.PS ,T2.SEC_ACCT_ID ,SSAI.SEC_ACCT_NAME ,T2.DEAL_CUR_ACCT as dealCurAcct ,c1.acctName as dealCurAcctName ,T1.PRICE_MODEL priceModel ,T2.DEAL_MODE as declaType , T1.PRICE as price /* ,T1.ENTRUST_AMT*NVL(T1.PRICE,1) ENTRUST_AMT*/ ,T1.ENTRUST_AMT entrustAmt ,nvl(T1.ENTRUST_NUM,0)/10000 as entrustNum ,T1.VDATE ,T1.MDATE ,T2.FULL_PRICE as fprice ,T2.MATURE_YIELD * 100 as yield ,T2.CAL_MODE as calMode ,T2.COUNTER_SEAT counterSeat ,T2.COUNTER_CON_NO counterConNo ,T1.ENTRUST_TYPE ,fpt.TYPE_8 paAssetType ,case WHEN T1.PS IN ('03','04') THEN T8.MARKET_ID when T1.ENTRUST_TYPE in ('09','12','13','14','16') then T7.FINPROD_MARKET_ID when T1.STOCK_ID IS NOT NULL THEN T1.STOCK_ID ELSE T7.FINPROD_MARKET_ID END finprodMarketId /*,T7.FINPROD_MARKET_ID finprodMarketId*/ ,T1.COUNTER_ID counterId ,T2.TARGET_TYPE ,T2.TRADER ,T2.COUNTER_ORG ,T1.COUNTER_TRADER ,T2.ASSET_TYPE assetType ,T1.CREATE_TIME ,T1.ENTRUST_DATE ,T1.INV_AIM ,T1.BUSINESS_MODEL businessModel ,T1.STOCK_ID ,T2.EXP_CON_NUM ,T2.DEAL_MODE dealMode ,T2.PRICE_TYPE priceType ,T1.REMARK remark FROM ETR_ENTRUST T1 INNER JOIN ETR_ENTRUST_ADD T2 ON T2.ENTRUST_ID = T1.ENTRUST_ID and (T2.ASSET_TYPE1 != 'H01' or T2.ASSET_TYPE1 is null) LEFT JOIN ETR_FINISH_STATUS T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID AND T1.ENTRUST_ID = T4.TRADE_ID LEFT JOIN PTL_PORTFOLIO T5 ON T5.PORTFOLIO_ID = T1.PORTFOLIO_ID
LEFT JOIN ( SELECT EED.ENTRUST_ID, listagg ( EED.PORTFOLIO_ID, ',' ) within GROUP ( ORDER BY EED.PORTFOLIO_ID ) AS PORTFOLIO_ID , listagg ( FP.PORTFOLIO_NAME, ',' ) within GROUP ( ORDER BY FP.PORTFOLIO_NAME ) AS PORTFOLIO_NAME FROM ETR_ENTRUST_DETAIL EED left join PTL_PORTFOLIO FP on EED.PORTFOLIO_ID = FP.PORTFOLIO_ID GROUP BY EED.ENTRUST_ID ) detail ON T1.ENTRUST_ID = detail.ENTRUST_ID
INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T6.PORTFOLIO_ID = T5.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT T7 ON T7.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T7.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON T2.SEC_ACCT_ID = SSAI.SEC_ACCT_ID
left join (select distinct ACCT_NO acctNo1, BUSI_ACCT_NO busiAcctNo1, CCY ccy, ACCT_NAME acctName from STL_CAPACCT_INFO) c1 on T2.DEAL_CUR_ACCT = c1.acctNo1 and nvl(T1.CCY, 'CNY') = c1.ccy left join MST_REPO_PRODUCT T8 on T1.FINPROD_ID = T8.TERM_TYPE where T1.TRADE_MARKET in ('03','04') AND T2.ASSET_TYPE NOT IN ('F17') AND T1.ENTRUST_TYPE IN (#{ENTRUST_BUSS_TYPE_30}) AND T1.CREATE_USER=#{userId}
AND T1.ENTRUST_DATE = to_date(#{sysDate},'yyyy-MM-dd')
AND T1.ENTRUST_ID LIKE CONCAT('%', CONCAT(#{entrustId}, '%'))
#{item}
AND T1.ENTRUST_DATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.INV_MANAGER_ID =#{invManagerId}
AND T1.FINPROD_ID =#{finprodMarketId}
#{item}
union all SELECT T1.ENTRUST_ID entrustId ,T1.ENTRUST_STATUS entrustStatus, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T4.ORDER_FINISH_AMT, 0 ),0,0, nvl( T4.ORDER_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_NUM, 1 )), 4 ) ELSE ROUND( decode(nvl( T4.ORDER_FINISH_AMT, 0 ),0,0, nvl( T4.ORDER_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_AMT, 1 )), 4 ) END AS implementPercent, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( decode(nvl( T4.ENT_FINISH_AMT, 0 ),0,0, nvl( T4.ENT_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_NUM, 1 )), 4 ) ELSE ROUND( decode(nvl( T4.ENT_FINISH_AMT, 0 ),0,0, nvl( T4.ENT_FINISH_AMT, 0 )/ nvl( T1.ENTRUST_AMT, 1 )), 4 ) END AS dealPercent, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T4.ORDER_FINISH_AMT/100, 0 ), 4 ) ELSE ROUND( nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) END AS finishAmt, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( (nvl( T1.ENTRUST_NUM, 0 ) - nvl( T4.ORDER_FINISH_AMT, 0 ))/100, 4 ) ELSE ROUND( nvl( T1.ENTRUST_AMT, 0 ) - nvl( T4.ORDER_FINISH_AMT, 0 ), 4 ) END AS avaNum, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( nvl( T4.ENT_FINISH_AMT/100, 0 ), 4 ) ELSE ROUND( nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) END AS finishDealAmt, CASE WHEN T2.TARGET_TYPE = '01' THEN ROUND( (nvl( T1.ENTRUST_NUM, 0 ) - nvl( T4.ENT_FINISH_AMT, 0 ))/100, 4 ) ELSE ROUND( nvl( T1.ENTRUST_AMT, 0 ) - nvl( T4.ENT_FINISH_AMT, 0 ), 4 ) END AS avaDealAmt, nvl(detail.PORTFOLIO_ID,T5.PORTFOLIO_ID) portfolioId, nvl(detail.PORTFOLIO_NAME,T5.PORTFOLIO_NAME) portfolioName, T1.FINPROD_ID finprodId ,T7.FINPROD_MARKET_ID AS FINPROD_MARKET_ID ,T7.FINPROD_ABBR AS finprodAbbr ,T1.FINPROD_TYPE2 finprodType2 ,T1.TRADE_MARKET tradeMarket ,T1.TRADE_PLAT ,T1.PS ,T2.SEC_ACCT_ID ,SSAI.SEC_ACCT_NAME ,T2.DEAL_CUR_ACCT ,c1.acctName as dealCurAcctName ,T1.PRICE_MODEL priceModel ,T2.DEAL_MODE as declaType , T1.PRICE as price /* ,T1.ENTRUST_AMT*NVL(T1.PRICE,1) ENTRUST_AMT*/ ,T1.ENTRUST_AMT entrustAmt, nvl(T1.ENTRUST_NUM,0)/10000 entrustNum ,T1.VDATE ,T1.MDATE ,T2.FULL_PRICE as fprice ,T2.MATURE_YIELD * 100 as yield ,T2.CAL_MODE as calMode ,T2.COUNTER_SEAT counterSeat ,T2.COUNTER_CON_NO counterConNo ,T1.ENTRUST_TYPE ,fpt.TYPE_8 paAssetType ,case WHEN T1.PS IN ('03','04') THEN T8.MARKET_ID when T1.ENTRUST_TYPE in ('09','12','13','14','16') then T7.FINPROD_MARKET_ID when T1.STOCK_ID IS NOT NULL THEN T1.STOCK_ID ELSE T7.FINPROD_MARKET_ID END finprodMarketId /*,T7.FINPROD_MARKET_ID finprodMarketId*/ ,T1.COUNTER_ID counterId ,T2.TARGET_TYPE ,T2.TRADER ,T2.COUNTER_ORG ,T1.COUNTER_TRADER ,T2.ASSET_TYPE assetType ,T1.CREATE_TIME ,T1.ENTRUST_DATE ,T1.INV_AIM ,T1.BUSINESS_MODEL businessModel ,T1.STOCK_ID ,T2.EXP_CON_NUM ,T2.DEAL_MODE dealMode ,T2.PRICE_TYPE priceType ,T1.REMARK remark FROM WFL_ETR_ENTRUST T1 INNER JOIN WFL_ETR_ENTRUST_ADD T2 ON T2.ENTRUST_ID = T1.ENTRUST_ID and (T2.ASSET_TYPE1 != 'H01' or T2.ASSET_TYPE1 is null) LEFT JOIN ETR_FINISH_STATUS T4 ON T4.ENTRUST_ID = T1.ENTRUST_ID AND T1.ENTRUST_ID = T4.TRADE_ID LEFT JOIN PTL_PORTFOLIO T5 ON T5.PORTFOLIO_ID = T1.PORTFOLIO_ID
LEFT JOIN ( SELECT EED.ENTRUST_ID, listagg ( EED.PORTFOLIO_ID, ',' ) within GROUP ( ORDER BY EED.PORTFOLIO_ID ) AS PORTFOLIO_ID , listagg ( FP.PORTFOLIO_NAME, ',' ) within GROUP ( ORDER BY FP.PORTFOLIO_NAME ) AS PORTFOLIO_NAME FROM WFL_ETR_ENTRUST_DETAIL EED left join PTL_PORTFOLIO FP on EED.PORTFOLIO_ID = FP.PORTFOLIO_ID GROUP BY EED.ENTRUST_ID ) detail ON T1.ENTRUST_ID = detail.ENTRUST_ID
INNER JOIN PTL_PORTFOLIO_AUTHORITY T6 ON T6.PORTFOLIO_ID = T5.PORTFOLIO_ID
AND T6.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT T7 ON T7.FINPROD_ID = T1.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE fpt ON fpt.FINPROD_ID = T7.FINPROD_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON T2.SEC_ACCT_ID = SSAI.SEC_ACCT_ID
left join (select distinct ACCT_NO acctNo1, BUSI_ACCT_NO busiAcctNo1, CCY ccy, ACCT_NAME acctName from STL_CAPACCT_INFO) c1 on T2.DEAL_CUR_ACCT = c1.acctNo1 and nvl(T1.CCY, 'CNY') = c1.ccy left join MST_REPO_PRODUCT T8 on T1.FINPROD_ID = T8.TERM_TYPE where T1.TRADE_MARKET in ('03','04') AND T2.ASSET_TYPE NOT IN ('F17') AND T1.ENTRUST_TYPE in (#{ENTRUST_BUSS_TYPE_30}) AND T1.CREATE_USER=#{userId}
AND T1.ENTRUST_DATE = to_date(#{sysDate},'yyyy-MM-dd')
AND T1.ENTRUST_ID LIKE CONCAT('%', CONCAT(#{entrustId}, '%'))
#{item}
AND T1.ENTRUST_DATE >=to_date(#{startDate},'yyyy-MM-dd')
AND T1.ENTRUST_DATE <=to_date(#{endDate},'yyyy-MM-dd')
AND T1.INV_MANAGER_ID =#{invManagerId}
AND T1.FINPROD_ID =#{finprodMarketId}
) T1 left join SYS_DATADICT_LIST sdl1 on T1.entrustStatus=sdl1.ITEM_CODE and sdl1.DICT_CODE='ENTRUST_STATUS' left join SYS_DATADICT_LIST sdl2 on T1.PS=sdl2.ITEM_CODE and sdl2.DICT_CODE='PS' left join SYS_DATADICT_LIST sdl3 on T1.tradeMarket=sdl3.ITEM_CODE and sdl3.DICT_CODE='TRADE_PLACE' left join SYS_DATADICT_LIST sdl4 on T1.priceModel=sdl4.ITEM_CODE and sdl4.DICT_CODE='PRICE_MODEL' LEFT JOIN SYS_DATADICT_LIST sdl5 ON T1.DECLATYPE=sdl5.ITEM_CODE AND sdl5.DICT_CODE='DECLA_TYPE' LEFT JOIN SYS_DATADICT_LIST sdl6 ON T1.FINPRODTYPE2=sdl6.ITEM_CODE AND sdl6.DICT_CODE='FINPROD_TYPE_TG' where 1=1
#{tradePlat,jdbcType=VARCHAR}
#{portfolioId,jdbcType=VARCHAR}
AND T1.PS = #{ps,jdbcType=VARCHAR}
AND T1.FINPROD_MARKET_ID = #{secId,jdbcType=VARCHAR}
AND T1.finprodId in
#{item, jdbcType=VARCHAR}
AND T1.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
#{item}
order by ${sort} ${direction}
ORDER BY T1.CREATE_TIME DESC

select

from  etr_entrust WHERE ENTRUST_ID = #{entrustId}
union all
select

from wfl_etr_entrust WHERE ENTRUST_ID = #{entrustId}

select

from  etr_entrust_add WHERE ENTRUST_ID = #{entrustId}
union all
select

from wfl_etr_entrust_add WHERE ENTRUST_ID = #{entrustId}

sql.if:
and ( T1.entrustId|| '|' ||sdl1.ITEM_VALUE|| '|' ||sdl2.ITEM_VALUE|| '|' ||sdl3.ITEM_VALUE|| '|' ||T1.portfolioId|| '|' ||T1.portfolioName|| '|' ||T1.finprodId|| '|' || T1.finprodAbbr|| '|' ||T1.assetType|| '|' || sdl4.ITEM_VALUE|| '|'|| sdl5.ITEM_VALUE|| '|'|| sdl6.ITEM_VALUE|| '|' || T1.dealCurAcctName|| '|' || T1.finprodMarketId|| '|' || T1.portfolioName like '%' || #{search} || '%' )
#{item}
or (T1.implementPercent*100 = #{search}) or (T1.dealPercent*100 = #{search}) or (T1.price = #{search}) or (T1.entrustAmt = #{search}) or (T1.entrustNum = #{search})

mapper.select:
SELECT TEMP.PORTFOLIO_ID AS portfolioId, PP.PORTFOLIO_NAME AS portfolioName, TEMP.SEC_ACCT_ID AS secAcctId, SSAI.SEC_ACCT_NAME AS secAcctName, TEMP.FINPROD_ID AS finprodId, FP.FINPROD_MARKET_ID AS finprodMarketId, FP.FINPROD_ABBR as finprodName, CASE WHEN instr(FP.FINPROD_MARKET_ID,'.') > 0 THEN SUBSTR(FP.FINPROD_MARKET_ID,1,instr(FP.FINPROD_MARKET_ID,'.',-1,1)-1) ELSE FP.FINPROD_MARKET_ID END AS secId, FP.FINPROD_ABBR AS secName, round(TEMP.AMOUNT/10000,2) AS positionsNum, invaim.INV_AIM as invAim, invaim.BUSINESS_MODEL as businessModel, invaim.TRADE_PLAT tradePlat, FP.FINPROD_TYPE2 AS finprodType2, FP.TRADE_MARKET AS tradeMarket, c1.acctNo1 AS acctNo, c1.acctName as dealCurAcctName, FPT.TYPE_8 assetType FROM ( SELECT A.CDATE AS CDATE, A.PORTFOLIO_ID AS PORTFOLIO_ID , A.SEC_ACCT_ID AS SEC_ACCT_ID , A.FINPROD_ID AS FINPROD_ID, SUM(A.AMOUNT) AMOUNT, SUM(A.ptlPositionsNum) ptlPositionsNum from( SELECT PSP.CDATE AS CDATE, PSP.PORTFOLIO_ID AS PORTFOLIO_ID , PSP.SEC_ACCT_ID AS SEC_ACCT_ID , PSP.FINPROD_ID AS FINPROD_ID, SUM(PSP.AMOUNT) AMOUNT, 0 as ptlPositionsNum FROM PTL_SEC_POSITION_RULE PSP INNER JOIN PTL_PORTFOLIO PP ON PSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE PSP.DATE_TYPE =0 AND PSP.HODING_TYPE=#{A_001} AND PSP.CDATE = #{sysDate} GROUP BY PSP.CDATE, PSP.PORTFOLIO_ID , PSP.SEC_ACCT_ID, PSP.FINPROD_ID union SELECT ETRPSP.CDATE AS CDATE, ETRPSP.PORTFOLIO_ID AS PORTFOLIO_ID , ETRPSP.SEC_ACCT_ID AS SEC_ACCT_ID , ETRPSP.FINPROD_ID, 0 AS AMOUNT, SUM(ETRPSP.AMOUNT) as ptlPositionsNum FROM ETR_SEC_POSITION_RULE ETRPSP INNER JOIN PTL_PORTFOLIO PP ON ETRPSP.PORTFOLIO_ID = PP.PORTFOLIO_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY PPA ON PP.PORTFOLIO_ID = PPA.PORTFOLIO_ID
AND PPA.USER_ID = #{userId}
WHERE ETRPSP.DATE_TYPE =0 AND ETRPSP.CDATE = #{sysDate} GROUP BY ETRPSP.CDATE, ETRPSP.PORTFOLIO_ID , ETRPSP.SEC_ACCT_ID, ETRPSP.FINPROD_ID) A GROUP BY A.CDATE, A.PORTFOLIO_ID , A.SEC_ACCT_ID, A.FINPROD_ID )TEMP LEFT JOIN FIN_PRODUCT FP ON TEMP.FINPROD_ID = FP.FINPROD_ID LEFT JOIN PTL_PORTFOLIO PP ON TEMP.PORTFOLIO_ID = PP.PORTFOLIO_ID LEFT JOIN STL_SEC_ACCT_INFO SSAI ON TEMP.SEC_ACCT_ID = SSAI.SEC_ACCT_ID left join (select distinct ACCT_NO acctNo1, BUSI_ACCT_NO busiAcctNo1, CCY ccy, ACCT_NAME acctName from STL_CAPACCT_INFO) c1 on SSAI.TRD_ACCT_ID = c1.acctNo1
left join ( select FINPROD_ID, PORTFOLIO_ID,TRADE_PLAT, listagg(INV_AIM, ',') WITHIN GROUP (ORDER BY PORTFOLIO_ID, FINPROD_ID) as INV_AIM, listagg(BUSINESS_MODEL, ',') WITHIN GROUP (ORDER BY PORTFOLIO_ID, FINPROD_ID) as BUSINESS_MODEL from ( SELECT FINPROD_ID, PORTFOLIO_ID, TRADE_PLAT,INV_AIM,BUSINESS_MODEL FROM ( select a.INV_AIM ,a.BUSINESS_MODEL, a.TRADE_DATE ,a.FINPROD_ID,b.PORTFOLIO_ID,a.TRADE_PLAT, ROW_NUMBER () over( PARTITION BY a.TRADE_ID ORDER BY a.TRADE_DATE DESC ) rn from TRD_PRODUCT_DEAL a LEFT JOIN TRD_PRODUCT_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID WHERE 1=1
AND b.PORTFOLIO_ID in
#{item}
AND a.TRADE_DATE <= #{sysDate} ) WHERE rn = 1 UNION SELECT a.FINPROD_ID, b.PORTFOLIO_ID, a.TRADE_PLAT,a.INV_AIM,a.BUSINESS_MODEL from TRD_PRODUCT_TEMP_DEAL a LEFT JOIN TRD_PRODUCT_TEMP_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID WHERE 1=1
AND b.PORTFOLIO_ID in
#{item}
AND a.TRADE_DATE = #{sysDate} ) GROUP BY FINPROD_ID, PORTFOLIO_ID,TRADE_PLAT ) invaim on invaim.FINPROD_ID=TEMP.FINPROD_ID and invaim.PORTFOLIO_ID=TEMP.PORTFOLIO_ID lEFT JOIN FIN_PRODUCT_TYPE FPT on FP.FINPROD_ID = FPT.FINPROD_ID WHERE FP.TRADE_MARKET IN (#{TRADE_PLACE_03}, #{TRADE_PLACE_04}) AND FP.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F37})
#{portfolioId,jdbcType=VARCHAR}
AND FP.FINPROD_ABBR LIKE CONCAT('%', CONCAT(#{finprodName}, '%'))
AND FP.TRADE_MARKET = #{tradeMarket,jdbcType=VARCHAR}
AND TEMP.SEC_ACCT_ID = #{secAcctId,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID = #{secId,jdbcType=VARCHAR}
AND FP.FINPROD_TYPE2 = #{finprodType2,jdbcType=VARCHAR}
AND FP.FINPROD_MARKET_ID = #{finprodMarketId,jdbcType=VARCHAR}
AND (FP.FINPROD_MARKET_ID in
#{item, jdbcType=VARCHAR}
) OR (FP.FINPROD_ID in
#{item, jdbcType=VARCHAR} )
AND FPT.TYPE_8 = #{assetType,jdbcType=VARCHAR}

select b.PORTFOLIO_ID , a.FINPROD_ID , a.INV_AIM , a.PS , a.UNIT_CPRICE AS PRICE, a.SHARE_AMT AS AMT from TRD_PRODUCT_DEAL a LEFT JOIN TRD_PRODUCT_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID LEFT JOIN FIN_PRODUCT c ON a.FINPROD_ID =c.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE d ON d.FINPROD_ID =a.FINPROD_ID WHERE a.TRADE_DATE =#{cdate} AND c.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F37} AND c.TRADE_MARKET in (#{SVR_TRADE_MARKET_03},#{SVR_TRADE_MARKET_04}) AND a.PS IN (#{PS_T01},#{PS_T02},#{PS_T04}) AND a.IS_CANCEL=#{YN_N}
AND b.PORTFOLIO_ID in
#{item}
AND a.FINPROD_ID in
#{item}
and d.TYPE_8 = #{secType1,jdbcType=VARCHAR}
union all select b.PORTFOLIO_ID , a.FINPROD_ID , a.INV_AIM , a.PS , a.UNIT_CPRICE AS PRICE, a.SHARE_AMT AS AMT from TRD_PRODUCT_TEMP_DEAL a LEFT JOIN TRD_PRODUCT_TEMP_DEAL_ADD b ON a.TRADE_ID =b.TRADE_ID LEFT JOIN FIN_PRODUCT c ON a.FINPROD_ID =c.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE d ON d.FINPROD_ID =a.FINPROD_ID WHERE a.TRADE_DATE =#{cdate}
AND c.FINPROD_TYPE2 =#{FINPROD_TYPE_TG_F37}
AND c.TRADE_MARKET in (#{SVR_TRADE_MARKET_03},#{SVR_TRADE_MARKET_04}) AND a.PS IN (#{PS_T01},#{PS_T02},#{PS_T04}) AND a.IS_CANCEL=#{YN_N}
AND b.PORTFOLIO_ID in
#{item}
AND a.FINPROD_ID in
#{item}
and d.TYPE_8 = #{secType1,jdbcType=VARCHAR}

select a.PORTFOLIO_ID, a.FINPROD_ID, sum(nvl(a.BUY_COST_AMT, 0)) BUY_COST_AMT, sum(nvl(a.SHARE_AMT, 0)) SHARE_AMT from PTL_SEC_UNITCOST a LEFT JOIN FIN_PRODUCT b ON a.FINPROD_ID =b.FINPROD_ID LEFT JOIN FIN_PRODUCT_TYPE c ON a.FINPROD_ID =c.FINPROD_ID WHERE (( b.FINPROD_TYPE2 in (#{FINPROD_TYPE_TG_F37}) AND b.TRADE_MARKET in(#{FINPROD_TYPE_TG_F37}) ) or (b.TRADE_MARKET in (#{SVR_TRADE_MARKET_03} ,#{SVR_TRADE_MARKET_04}))) AND a.CDATE =#{cdate}
AND a.PORTFOLIO_ID in
#{item}
AND b.FINPROD_ID in
#{item}
and c.TYPE_8 = #{secType1,jdbcType=VARCHAR}
GROUP BY a.PORTFOLIO_ID, a.FINPROD_ID ORDER BY a.PORTFOLIO_ID, a.FINPROD_ID
